SELECT id, title, category, priority, due_date, completed, completed_at, pinned, created_at, updated_at FROM todos
AND title LIKE CONCAT('%', #{keyword}, '%')
AND category = #{category}
AND due_date >= #{from}
AND due_date <= #{to}
ORDER BY due_date
DESC ASC

